/**
 * Alternative: Download as PDF using browser's built-in functionality
 */
export const downloadInvoiceAsPDF = async (invoiceId: string, invoiceNumber: string) => {
    try {
        // Trigger browser print which can save as PDF
        const printContent = document.getElementById('invoice-content');
        if (!printContent) {
            console.error('Invoice content not found');
            return;
        }

        // Create a new window with the content
        const printWindow = window.open('', '_blank');
        if (!printWindow) {
            console.error('Could not open print window');
            return;
        }

        // Copy styles and content
        const styles = Array.from(document.styleSheets)
            .map(styleSheet => {
                try {
                    return Array.from(styleSheet.cssRules)
                        .map(rule => rule.cssText)
                        .join('\n');
                } catch (e) {
                    return '';
                }
            })
            .join('\n');

        printWindow.document.write(`
            <!DOCTYPE html>
            <html>
                <head>
                    <title>Invoice ${invoiceNumber}</title>
                    <style>${styles}</style>
                    <style>
                        @media print {
                            body { margin: 0; padding: 20px; }
                            .no-print { display: none !important; }
                        }
                    </style>
                </head>
                <body>
                    ${printContent.innerHTML}
                </body>
            </html>
        `);

        printWindow.document.close();

        setTimeout(() => {
            printWindow.print();
        }, 500);
    } catch (error) {
        console.error('Error generating PDF:', error);
    }
};

